def top_k(lst, k):
    if lst == [] or k == 0:
        return []
    elif k == 0:
        return lst
    else:
        final = []
        while lst:
            element = max(lst)
            final += [element,]
            lst.remove(element)
            if len(final) == k:
                break
        return final

def top_k(lst, k):
    i=0
    while i+1<len(lst):
        if lst[i]<lst[i+1]:
            lst.extend([lst[i]])
            lst.pop(i)
            i=0
        else:
            i+=1
    return lst[:k]

def top_k(lst, k):
    #top k in descending order
    sort = []
    x=len(lst)
    while len(lst)>x-k:
        largest = lst[0]
        for element in lst:
            if element > largest:
                largest = element
        lst.remove(largest)
        sort.append(largest)
    return sort

def top_k(lst, k):
    sorted_lst = []
    while lst:
        biggest = lst[0]
        for n in range(len(lst)):
            if lst[n] >= biggest:
                biggest = lst[n]
        lst.remove(biggest)
        sorted_lst.append(biggest)
    return sorted_lst[0:k]

