def top_k(lst, k):
    if k>len(lst):
        return None
    def newsort(lsts):
        l=[]
        while lsts:
            a=lsts[0]
            for element in lsts:
                if element>a:
                    a=element
            l.append(a)
            lsts.remove(a)
        return l
    newlist=newsort(lst)
    return newlist[0:k]


